export function migrateExistingDataToNewClassification(
  newClassificationRules: Array<{ documentType: string; processingRoute: string; paperStorageRequired: boolean }>,
  existingDocuments: Array<{ id: string; current_processing_route: string }>,
  migrationScope: string
): MigrationResult {
  if (newClassificationRules.length === 0) {
    throw new Error("法令改正に基づく新しい分類基準が設定されていません。分類基準を確認してください。");
  }
  
  const targetDocuments = existingDocuments.filter(doc => isInMigrationScope(doc, migrationScope));
  let migratedCount = 0;
  let skippedCount = 0;
  let errorCount = 0;
  const updatedRoutes: Array<{ documentId: string; oldRoute: string; newRoute: string }> = [];
  
  for (const document of targetDocuments) {
    try {
      const newClassification = applyNewRulesInternal(document, newClassificationRules);
      if (newClassification.processingRoute !== document.current_processing_route) {
        updateDocumentRouteInternal(document.id, newClassification);
        updatedRoutes.push({
          documentId: document.id,
          oldRoute: document.current_processing_route,
          newRoute: newClassification.processingRoute
        });
        migratedCount++;
      } else {
        skippedCount++;
      }
    } catch (error) {
      errorCount++;
    }
  }
  
  return { migratedCount, skippedCount, errorCount, updatedRoutes };
}

function extractComplianceKeywords(regulationNotice: string): string[] {
  if (!regulationNotice || regulationNotice.trim() === '') {
    return [];
  }
  
  const keywords = [];
  if (regulationNotice.includes('補助金')) keywords.push('補助金');
  if (regulationNotice.includes('研究費')) keywords.push('研究費');
  if (regulationNotice.includes('申請書')) keywords.push('申請書');
  if (regulationNotice.includes('紙保管')) keywords.push('紙保管');
  if (regulationNotice.includes('電子保管')) keywords.push('電子保管');
  
  return keywords;
}

function isAffectedByRegulationInternal(docType: string, keywords: string[]): boolean {
  if (!docType || docType.trim() === '') return false;
  
  return keywords.some(keyword => docType.includes(keyword));
}

function evaluateNewPaperRequirementInternal(docType: string, regulationNotice: string): boolean {
  if (regulationNotice.includes('電子保管を許可') && docType.includes('研究費')) {
    return false;
  }
  if (regulationNotice.includes('紙保管要件が変更') && docType.includes('補助金')) {
    return true;
  }
  return true;
}

function determineEmergencyLevelInternal(affectedCount: number, regulationNotice: string): string {
  if (affectedCount > 100) return 'critical';
  if (affectedCount >= 2 || regulationNotice.includes('補助金')) return 'high';
  if (affectedCount >= 1) return 'medium';
  return 'low';
}

function getNotificationTargetsInternal(affectedTypes: string[], emergencyLevel: string): string[] {
  if (emergencyLevel === 'critical' || emergencyLevel === 'high') {
    return ['広報課', '財務課', '各学部事務'];
  }
  if (emergencyLevel === 'medium') {
    return ['財務課', '各学部事務'];
  }
  return ['財務課'];
}

export function handleEmergencyComplianceUpdate(
  regulationNotice: string,
  currentDocumentTypes: string[],
  existingProcessingRoutes: Array<{ documentType: string; processingRoute: string; paperStorageRequired: boolean }>
): EmergencyComplianceResult {
  // 法令改正通知の内容検証
  if (!regulationNotice || regulationNotice.trim() === '' || regulationNotice === '無効な文字列###') {
    throw new Error('法令改正通知の内容を正しく読み込めませんでした。通知内容を確認してください。');
  }

  // 現在の申請書類種別データの検証
  if (!currentDocumentTypes || currentDocumentTypes.length === 0) {
    throw new Error('システムエラーにより申請書類の種別情報を取得できませんでした。システム管理者に連絡してください。');
  }

  // 処理ルート設定データの検証
  if (!existingProcessingRoutes) {
    throw new Error('システムエラーにより申請書類の種別情報を取得できませんでした。システム管理者に連絡してください。');
  }

  const keywords = extractComplianceKeywords(regulationNotice);
  const affectedTypes = [];
  
  for (const docType of currentDocumentTypes) {
    if (docType && docType.trim() !== '' && isAffectedByRegulationInternal(docType, keywords)) {
      affectedTypes.push(docType);
    }
  }

  const updatedRoutes = [];
  for (const docType of affectedTypes) {
    const newPaperRequired = evaluateNewPaperRequirementInternal(docType, regulationNotice);
    const newRoute = newPaperRequired ? "hybrid" : "electronic";
    updatedRoutes.push({ 
      documentType: docType, 
      processingRoute: newRoute, 
      paperStorageRequired: newPaperRequired 
    });
  }

  const emergencyLevel = determineEmergencyLevelInternal(affectedTypes.length, regulationNotice);
  const notificationTargets = getNotificationTargetsInternal(affectedTypes, emergencyLevel);

  return { 
    affectedDocumentTypes: affectedTypes, 
    updatedRoutes, 
    notificationTargets, 
    emergencyLevel 
  };
}
